-- Local-only Feature 18 immutable ledger. It never reads or projects product policy state.
CREATE TABLE IF NOT EXISTS mandate_policy_scopes (scope_hash char(64) PRIMARY KEY CHECK(scope_hash~'^[a-f0-9]{64}$'), operator_test_id text NOT NULL, tenant_fingerprint text NOT NULL, user_fingerprint text NOT NULL, account_fingerprint text NOT NULL, environment text NOT NULL CHECK(environment IN ('local','test')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(operator_test_id,tenant_fingerprint,user_fingerprint,account_fingerprint,environment));
CREATE TABLE IF NOT EXISTS mandate_policy_registry_snapshots (artifact_hash char(64) PRIMARY KEY CHECK(artifact_hash~'^[a-f0-9]{64}$'), scope_hash char(64) NOT NULL REFERENCES mandate_policy_scopes(scope_hash), registry_version text NOT NULL DEFAULT 'v1', payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS mandate_policy_mandates (artifact_hash char(64) PRIMARY KEY CHECK(artifact_hash~'^[a-f0-9]{64}$'), scope_hash char(64) NOT NULL REFERENCES mandate_policy_scopes(scope_hash), revision integer NOT NULL CHECK(revision>0), predecessor_hash char(64) CHECK(predecessor_hash IS NULL OR predecessor_hash~'^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_hash,artifact_hash), UNIQUE(scope_hash,revision), UNIQUE(scope_hash,predecessor_hash));
CREATE TABLE IF NOT EXISTS mandate_policy_artifact_links (scope_hash char(64) NOT NULL, artifact_hash char(64) NOT NULL CHECK(artifact_hash~'^[a-f0-9]{64}$'), target_scope_hash char(64) NOT NULL, target_artifact_hash char(64) NOT NULL CHECK(target_artifact_hash~'^[a-f0-9]{64}$'), relation text NOT NULL CHECK(relation IN ('mandate','registry','mapping','coverage','test','diff','challenge','consent','activation','boundary','history','bundle')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope_hash,artifact_hash,target_scope_hash,target_artifact_hash,relation), CHECK(scope_hash=target_scope_hash), FOREIGN KEY(scope_hash) REFERENCES mandate_policy_scopes(scope_hash), FOREIGN KEY(target_scope_hash) REFERENCES mandate_policy_scopes(scope_hash));
DO $$ DECLARE n text; ns text[]:=ARRAY['mandate_policy_draft_projections','mandate_policy_clause_mappings','mandate_policy_coverage_receipts','mandate_policy_compilations','mandate_policy_test_manifests','mandate_policy_test_receipts','mandate_policy_semantic_diffs','mandate_policy_diff_items','mandate_policy_consent_challenges','mandate_policy_consent_receipts','mandate_policy_activation_receipts','mandate_policy_boundary_receipts','mandate_policy_history_append_receipts','mandate_policy_transitions','mandate_policy_conflicts','mandate_policy_request_claims','mandate_policy_test_center_bundles']; BEGIN FOREACH n IN ARRAY ns LOOP EXECUTE format('CREATE TABLE IF NOT EXISTS %I (artifact_hash char(64) PRIMARY KEY CHECK(artifact_hash~''^[a-f0-9]{64}$''), scope_hash char(64) NOT NULL REFERENCES mandate_policy_scopes(scope_hash), operator_test_id text NOT NULL, idempotency_key text, request_hash char(64) CHECK(request_hash IS NULL OR request_hash~''^[a-f0-9]{64}$''), predecessor_hash char(64) CHECK(predecessor_hash IS NULL OR predecessor_hash~''^[a-f0-9]{64}$''), sequence integer CHECK(sequence IS NULL OR sequence>0), run_id text, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(scope_hash,artifact_hash))',n); EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS request_hash char(64)',n); EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS predecessor_hash char(64)',n); EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS sequence integer',n); EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS run_id text',n); END LOOP; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_mapping_field_case ON mandate_policy_clause_mappings(scope_hash,(payload->>'fieldName'),(payload->>'caseId'));
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_coverage_field ON mandate_policy_coverage_receipts(scope_hash,(payload->>'fieldName'));
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_test_case ON mandate_policy_test_receipts(scope_hash,(payload->>'caseId'));
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_challenge_nonce_unique ON mandate_policy_consent_challenges(scope_hash,(payload->>'nonceHash'));
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_consent_once ON mandate_policy_consent_receipts(scope_hash,(payload->>'challengeNonceHash'));
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_activation_sequence ON mandate_policy_activation_receipts(scope_hash,sequence);
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_activation_predecessor ON mandate_policy_activation_receipts(scope_hash,coalesce(predecessor_hash,repeat('0',64)));
CREATE UNIQUE INDEX IF NOT EXISTS mandate_policy_request_claim_unique ON mandate_policy_request_claims(operator_test_id,idempotency_key);
CREATE INDEX IF NOT EXISTS mandate_policy_activation_fold ON mandate_policy_activation_receipts(scope_hash,sequence DESC);
CREATE INDEX IF NOT EXISTS mandate_policy_bundle_run ON mandate_policy_test_center_bundles(run_id);
DO $$ BEGIN IF to_regclass('agent_test_center_runs') IS NOT NULL THEN ALTER TABLE mandate_policy_test_center_bundles DROP CONSTRAINT IF EXISTS mandate_policy_bundle_generic_run; ALTER TABLE mandate_policy_test_center_bundles ADD CONSTRAINT mandate_policy_bundle_generic_run FOREIGN KEY(run_id) REFERENCES agent_test_center_runs(run_id); END IF; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE OR REPLACE FUNCTION mandate_policy_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'mandate_policy_append_only'; END $$;
DO $$ DECLARE n text; ns text[]:=ARRAY['mandate_policy_scopes','mandate_policy_registry_snapshots','mandate_policy_mandates','mandate_policy_artifact_links','mandate_policy_draft_projections','mandate_policy_clause_mappings','mandate_policy_coverage_receipts','mandate_policy_compilations','mandate_policy_test_manifests','mandate_policy_test_receipts','mandate_policy_semantic_diffs','mandate_policy_diff_items','mandate_policy_consent_challenges','mandate_policy_consent_receipts','mandate_policy_activation_receipts','mandate_policy_boundary_receipts','mandate_policy_history_append_receipts','mandate_policy_transitions','mandate_policy_conflicts','mandate_policy_request_claims','mandate_policy_test_center_bundles']; BEGIN FOREACH n IN ARRAY ns LOOP EXECUTE format('DROP TRIGGER IF EXISTS mandate_policy_immutable ON %I',n); EXECUTE format('CREATE TRIGGER mandate_policy_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION mandate_policy_append_only()',n); END LOOP; END $$;
